package com.mahesh.empleave.employee;

import com.mahesh.empleave.audit.*;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.department.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.security.crypto.password.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;

@RestController @RequestMapping("/api/employees") @RequiredArgsConstructor public class EmployeeController {
 private final UserRepository users; private final DepartmentRepository departments; private final PasswordEncoder encoder; private final AuditService audit;
 record Create(@Email @NotBlank String email,@NotBlank @Size(max=160) String fullName,@NotBlank @Size(min=8,max=100) String password,Role role,Long departmentId,Long managerId){}
 record Update(@NotBlank @Size(max=160) String fullName,Long departmentId,Long managerId){}
 @GetMapping("/me") @Transactional(readOnly=true) EmployeeProfile me(Authentication a){return EmployeeProfile.from(users.findByEmail(a.getName()).orElseThrow());}
 @GetMapping @PreAuthorize("hasRole('ADMIN')") Page<ApiDtos.Employee> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) Role role){var request=PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),Sort.by("fullName"));return (role==null?users.findAll(request):users.findByRole(role,request)).map(ApiDtos::employee);}
 @GetMapping("/{id}") ApiDtos.Employee one(Authentication a,@PathVariable Long id){var target=users.findById(id).orElseThrow();var actor=users.findByEmail(a.getName()).orElseThrow();if(!target.getId().equals(actor.getId())&&actor.getRole()!=Role.ADMIN&&(target.getManager()==null||!target.getManager().getId().equals(actor.getId())))throw new SecurityException("Access denied");return ApiDtos.employee(target);}
 @PostMapping @PreAuthorize("hasRole('ADMIN')") ApiDtos.Employee create(Authentication a,@RequestBody @jakarta.validation.Valid Create x){if(users.existsByEmail(x.email()))throw new IllegalArgumentException("Email already exists");var u=new AppUser(x.email(),encoder.encode(x.password()),x.role()==null?Role.EMPLOYEE:x.role(),x.fullName());apply(u,x.fullName(),x.departmentId(),x.managerId());u=users.save(u);audit.log(users.findByEmail(a.getName()).orElseThrow(),"EMPLOYEE_CREATED","EMPLOYEE",u.getId());return ApiDtos.employee(u);}
 @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ApiDtos.Employee update(Authentication a,@PathVariable Long id,@RequestBody @jakarta.validation.Valid Update x){var u=users.findById(id).orElseThrow();apply(u,x.fullName(),x.departmentId(),x.managerId());u=users.save(u);audit.log(users.findByEmail(a.getName()).orElseThrow(),"EMPLOYEE_UPDATED","EMPLOYEE",u.getId());return ApiDtos.employee(u);}
 private void apply(AppUser u,String name,Long deptId,Long managerId){Department d=deptId==null?null:departments.findById(deptId).orElseThrow();AppUser m=managerId==null?null:users.findById(managerId).orElseThrow();if(m!=null&&m.getRole()!=Role.MANAGER)throw new IllegalArgumentException("Assigned manager must have MANAGER role");u.update(name,d,m,u.getRole());}
}
